"""Practice sets for core pure mathematics (A Level): Trigonometry and Coordinate Geometry, in-depth lessons.

KKEVO draft questions written against the lessons in apps/courses/lesson_content/a_pure_03_trig_conics.py.
They are original practice questions, not past-paper questions. A reviewer checks them before publishing.
"""

from .dsl import *  # noqa: F403

COURSE = [("pure-mathematics-with-mechanics", "lower-sixth"),
          ("pure-mathematics-with-statistics", "lower-sixth")]

MODULE = "Trigonometry & Coordinate Geometry"
IDENT = "Identities"
CONICS = "Conic sections"


def _mc(prompt, texts, ci, whys, steps, concept, skill, hint, feedback):
    """Four-option MC: texts in display order, ci = index of the correct one, whys = reasons for the wrong ones in order."""
    wrong = iter(whys)
    choices = [C(t, correct=True) if i == ci else C(t, why=next(wrong)) for i, t in enumerate(texts)]
    return MC(prompt, choices, steps, concept=concept, skill=skill, hint=hint, feedback=feedback)


